 const b=t.B,ids=t.playerGroups(),g=b.groups[ids[0]],bow=b.groups[ids[1]],h=b.groups.hero,right=Object.values(b.groups).filter(q=>q.foe),chosen=right[0],other=right[1],champ=right[2],us=g.units,es=chosen.units,os=other.units;
