 us[0].x=200;us[0].y=200;us[1].x=200;us[1].y=300;es.forEach((u,i)=>{u.x=260;u.y=200+i*50});os.forEach((u,i)=>{u.x=235;u.y=220+i*90});
 g.attack(es[1]);ok(g.targetGroupId===chosen.id&&g.targetUnitId===es[1].id&&g.tgt===es[1],'attacking a soldier records its exact formation identity');
 t.aiUnit(us[0],.01,()=>{});t.aiUnit(us[1],.01,()=>{});ok(us[0].tgt===es[0]&&us[1].tgt===es[2],'different soldiers select nearby opponents inside the chosen formation');
