 const p=g.targetPoint();ok(p.x===es[2].x&&p.y===es[2].y,'target marker position follows surviving formation members, not a corpse');
 es[0].hp=es[1].hp=10000;os[0].x=us[0].x+5;os[0].y=us[0].y;us[0].rt=0;us[0].cd=0;const hit=[];t.aiUnit(us[0],.01,(u,e)=>hit.push(e));
