 const ar=bow.units;ar.forEach((u,i)=>{u.x=200;u.y=200+i*80;u.rt=0;u.s={...u.s,range:180};u.shot=null;u.cd=0});bow.face=bow.currentFacing=0;bow.cease=true;bow.attack(es[0]);
 es[0].x=150;es[0].y=200;es[1].x=300;es[1].y=200;es[2].x=300;es[2].y=280;
 t.aiUnit(ar[0],.01,()=>{});t.aiUnit(ar[1],.01,()=>{});ok(ar[0].tgt===es[1]&&ar[1].tgt===es[2]&&ar.every(u=>u.shot),'ordered archers choose in-range forward members independently, including under cease fire');
 es.forEach(u=>u.x=150);ar.forEach(u=>{u.rt=0;u.shot=null});t.aiUnit(ar[0],.01,()=>{});ok(!ar[0].shot&&!t.inArc(ar[0],ar[0].tgt),'group targeting cannot bypass a shooter firing arc');
 es.forEach(u=>u.x=650);ar[0].rt=0;ar[0].shot=null;t.aiUnit(ar[0],.01,()=>{});ok(!ar[0].shot,'group targeting cannot bypass individual weapon range');
 es.forEach(u=>u.rout=true);g.step(.01);ok(g.order==='charge'&&g.targetGroupId===chosen.id&&g.targetMembers().length===3,'an explicit attack continues to pursue routing members on the field');
 es.forEach(u=>{u.rout=false;u.hp=10000});chosen.withdraw();g.step(.01);ok(g.order==='charge'&&g.tgt,'withdrawing members remain valid until they actually leave the field');
 es.forEach(u=>{u.left=true;u.hpLeft=u.hp;u.hp=0});g.step(.01);ok(g.order==='hold'&&!g.hasTarget&&!g.tgt,'after the target formation exits, attackers hold rather than auto-charge another group');
 chosen.hold();es.forEach(u=>{u.left=false;u.hp=10000});g.attack(chosen);ok(g.targetGroupId===chosen.id&&g.tgt,'the shared order API also accepts an enemy formation directly');
 g.attack(os[0]);ok(g.targetGroupId===other.id,'a new explicit order selects the other duplicate formation');g.hold();ok(!g.hasTarget,'Hold clears formation focus');
 g.attack(es[0]);g.attack(new t.BattleControl('missing',1));ok(g.targetGroupId===chosen.id,'an unavailable target cannot silently discard a valid attack order');
 g.attack(es[0]);g.moveTo(250,250);ok(!g.hasTarget,'a ground move cancels explicit formation focus');g.attack(es[0]);g.withdraw();ok(!g.hasTarget,'withdrawal cancels explicit formation focus');
 g.attack(es[0]);g.charge();ok(!g.hasTarget&&g.order==='charge','general charge remains an untargeted order');g.attack(es[0]);g.hold();g.attack(us[0]);ok(!g.hasTarget&&g.order==='hold','friendly formations are rejected without changing the existing order');
 g.attack(es[0]);es.forEach(u=>u.hp=0);g.step(.01);ok(g.order==='hold'&&!g.hasTarget,'a destroyed formation also ends pursuit with Hold');
 es.forEach(u=>u.hp=10000);g.attack(champ.units[0]);ok(g.targetGroupId===champ.id&&g.targetMembers().length===1,'single-character formations use the same group targeting contract');
